const items = $input.all();

function stripFences(s) {
  return String(s)
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function firstJsonLike(s) {
  if (typeof s !== 'string') return null;

  const mObj = s.match(/{[\s\S]*}/);
  if (mObj && mObj[0]) return mObj[0];

  const mArr = s.match(/\[[\s\S]*\]/);
  if (mArr && mArr[0]) return mArr[0];
  return null;
}

function parseMaybe(any) {
  if (any == null) return null;
  if (typeof any === 'object') return any;

  if (typeof any === 'string') {
    const txt = stripFences(any);
    try {
      return JSON.parse(txt);
    } catch (e) {}

    const picked = firstJsonLike(txt);
    if (picked) {
      try {
        return JSON.parse(picked);
      } catch (e2) {}
    }
  }

  return null;
}

function tryFromJson(j) {
  if (!j || typeof j !== 'object') return null;

  let raw = null;

  if (j.output !== undefined) raw = j.output;
  else if (j.text !== undefined) raw = j.text;
  else if (j.message !== undefined) raw = j.message;
  else raw = j;

  if (raw && typeof raw === 'object' && raw.action === 'parse' && typeof raw.text === 'string') {
    const parsedFromAction = parseMaybe(raw.text);
    if (parsedFromAction) return parsedFromAction;
  }

  const parsed = parseMaybe(raw);
  if (parsed) return parsed;

  if (raw && typeof raw === 'object') {
    for (const key in raw) {
      if (!Object.prototype.hasOwnProperty.call(raw, key)) continue;
      const v = raw[key];
      const p = parseMaybe(v);
      if (p) return p;
    }
  }

  return null;
}

let payload = null;

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const p = tryFromJson(j);
  if (p) {
    payload = p;
    break;
  }
}

if (!payload) {
  throw new Error('No parsable JSON found in upstream output, please check if AI Agent output valid JSON.');
}

return [
  {
    json: payload
  }
];

const items = $input.all();

function stripFences(s) {
  return String(s)
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function tryParseJsonFromString(s) {
  if (typeof s !== 'string') return null;
  const txt = stripFences(s);

  try {
    return JSON.parse(txt);
  } catch (e) {}

  const mArr = txt.match(/\[[\s\S]*\]/);
  if (mArr && mArr[0]) {
    try {
      return JSON.parse(mArr[0]);
    } catch (e2) {}
  }

  const mObj = txt.match(/{[\s\S]*}/);
  if (mObj && mObj[0]) {
    try {
      return JSON.parse(mObj[0]);
    } catch (e3) {}
  }

  return null;
}

function pickPayload(any, depth) {
  if (depth === undefined) depth = 0;
  if (any == null || depth > 4) return null;

  if (typeof any === 'object' && !Array.isArray(any)) {
    return any;
  }

  if (typeof any === 'string') {
    const j = tryParseJsonFromString(any);
    if (j && typeof j === 'object') return j;
    return any;
  }

  if (Array.isArray(any) && any.length > 0) {
    const first = any[0];
    return pickPayload(first, depth + 1);
  }

  return null;
}

function extractRawFromItemJson(j) {
  if (!j || typeof j !== 'object') return null;

  const candidates = [];
  candidates.push(j);

  if (j.output != null)   candidates.push(j.output);
  if (j.text != null)     candidates.push(j.text);
  if (j.message != null)  candidates.push(j.message);
  if (j.data != null)     candidates.push(j.data);
  if (j.response != null) candidates.push(j.response);

  for (let i = 0; i < candidates.length; i++) {
    const hit = pickPayload(candidates[i], 0);
    if (hit != null) return hit;
  }

  for (const k of Object.keys(j)) {
    const v = j[k];
    if (typeof v === 'string' && v.trim()) {
      return v;
    }
  }

  return null;
}

let raw = null;
if (items.length > 0) {
  const j = items[0].json || {};
  raw = extractRawFromItemJson(j);
}

let payload;

if (raw == null) {
  payload = {
    protocol_text: 'The content for "Synthesis and Reporting/Reporting Plan" has not been successfully generated yet and will be supplemented when the research design information is further refined.'
  };
}

else if (typeof raw === 'string') {
  const parsed = tryParseJsonFromString(raw);
  if (parsed && typeof parsed === 'object') {
    payload = parsed;
  } else {
    payload = {
      protocol_text: stripFences(raw)
    };
  }
}

else if (typeof raw === 'object') {
  if (Array.isArray(raw)) {
    payload = { list: raw };
  } else {
    payload = raw;
  }
}

else {
  payload = {
    protocol_text: String(raw)
  };
}

return [
  {
    json: payload
  }
];

